import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { login, register, getToken } from '@/services/auth';
import type { User } from '@/types';

// Authoritative Session Verification Hook
export function useAuthSession() {
  return useQuery({
    queryKey: ['authUser'],
    queryFn: async () => {
      const token = getToken();
      if (!token) throw new Error('No authentication token found.');

      const backendUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000';
      const response = await fetch(`${backendUrl}/api/user`, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      if (!response.ok) {
        throw new Error('Session verification failed. Unauthorized access.');
      }

      return response.json();
    },
    retry: false,
    staleTime: 1000 * 60 * 5, // Cache the authoritative user object for 5 minutes
  });
}

export function useAuth(onSuccess: (user: User) => void) {
  const queryClient = useQueryClient();
  const [isLogin, setIsLogin] = useState(true);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [name, setName] = useState('');

  const authMutation = useMutation({
    mutationFn: async () => {
      const result = isLogin
        ? await login(email, password)
        : await register(username, name, email, password);

      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: (data) => {
      // Seed the cache with the trusted server response directly
      queryClient.setQueryData(['authUser'], data.user);
      onSuccess(data.user);
    }
  });

  const toggleAuthMode = () => {
    setIsLogin(!isLogin);
    authMutation.reset();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    authMutation.mutate();
  };

  return {
    isLogin, toggleAuthMode,
    isLoading: authMutation.isPending,
    error: authMutation.error?.message || null,
    email, setEmail,
    password, setPassword,
    username, setUsername,
    name, setName,
    handleSubmit
  };
}

import { useCallback } from 'react';

export function useDynamicList(
  list: T[] = [],
  onChange: (newList: T[]) => void
) {
  const add = useCallback((newItem: T) => {
    onChange([...list, newItem]);
  }, [list, onChange]);

  const update = useCallback((index: number, field: keyof T, value: any) => {
    const newList = [...list];
    newList[index] = { ...newList[index], [field]: value };
    onChange(newList);
  }, [list, onChange]);

  const updatePrimitive = useCallback((index: number, value: T) => {
    const newList = [...list];
    newList[index] = value;
    onChange(newList);
  }, [list, onChange]);

  const remove = useCallback((index: number, resequenceField?: keyof T) => {
    let newList = list.filter((_, i) => i !== index);
    if (resequenceField) {
      // Safely map and re-assign the sequence field (e.g., page_number)
      newList = newList.map((item, i) => ({ ...item, [resequenceField]: i + 1 }));
    }
    onChange(newList);
  }, [list, onChange]);

  return { items: list, add, update, updatePrimitive, remove };
}

import { useMutation, type UseMutationResult } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import { useRoomActions, type ToastNotification } from '@/context/RoomContext';
import type { Result } from '@/utils/Result';
import { getSafeString } from '@/utils/parsers';

/**
 * Unified mutation wrapper for every game action.
 *
 * Before this hook, each of the six game mutations in `useInvestigationPhase`,
 * `useSuspectVerdict` and `useInvestigationRequest` repeated the same three
 * things by hand:
 *   1. unwrap the `Result` from `@/services/api` and throw on failure,
 *   2. reach into a half-known error shape to find a renderable string,
 *   3. push a `GlobalFeedback` object into `RoomContext`.
 *
 * Those copies drifted: some kept the server `title`, some discarded it, some
 * silently swallowed a `SyntaxError`. Centralising them here is what makes the
 * error path uniform -- and therefore testable.
 *
 * `mutationFn` receives a `Result`-returning function. The hook owns the
 * unwrap-then-throw contract, so callers never write `if (!result.isSuccess)`
 * again.
 */

/** Feedback stays on screen this long, matching the pre-existing modal timings. */
export const DEFAULT_FEEDBACK_TTL = 4000;

/** Translation key used when a mutation fails and no `errorTitle` is supplied. */
export const DEFAULT_ERROR_TITLE_KEY = 'pages.gameRoom.hooks.phase.systemError';

export type FeedbackToastType = ToastNotification['type'];

export interface GameMutationConfig {
  /** Must resolve to a `Result`. The failure branch is unwrapped into a thrown `Error`. */
  mutationFn: (vars: TVars) => Promise<Result>;

  /**
   * Translation key (or literal text) dispatched as a success feedback.
   * Omit it and success stays silent, which is the correct default for
   * mutations whose success is already visible in the UI (a refresh, a
   * state change).
   */
  successMessage?: string;
  /** Title for the success feedback. Defaults to `successMessage`. */
  successTitle?: string;
  /** Route the success notice to a toast instead of the global feedback modal. */
  successToast?: FeedbackToastType;
  /** Icon for `successToast`. */
  successIcon?: string;

  /** Translation key (or literal text) used as the error feedback title. */
  errorTitle?: string;

  /**
   * Set to `false` when the caller renders its own feedback surface.
   *
   * `useSuspectVerdict` and `useInvestigationRequest` both drive a tab-local
   * modal (indictment / procedural request) rather than the global overlay,
   * so for them the unified error dispatch would raise a second, duplicate
   * notification. Defaults to `true`.
   */
  dispatchErrorFeedback?: boolean;

  /** Milliseconds before the success feedback auto-dismisses. */
  feedbackTtl?: number;

  /** Optimistic-update hook. The returned value is the rollback context. */
  onMutate?: (vars: TVars) => Promise | TContext;
  /** Runs *after* the unified success feedback has been dispatched. */
  onSuccess?: (data: TData, vars: TVars, context: TContext | undefined) => void;
  /** Runs *after* the unified error feedback has been dispatched. */
  onError?: (error: Error, vars: TVars, context: TContext | undefined) => void;
  onSettled?: (
    data: TData | undefined,
    error: Error | null,
    vars: TVars,
    context: TContext | undefined,
  ) => void;
}

/**
 * Normalises anything thrown inside a `mutationFn` into a real `Error`.
 *
 * The guard clauses the callers write before hitting the API
 * (`throw { message: 'No active level to submit.' }`) would otherwise reach
 * `onError` as a bare object, and `error.message` would be readable by
 * accident rather than by contract.
 */
const toError = (thrown: unknown): Error => {
  if (thrown instanceof Error) return thrown;

  const message = getSafeString(thrown, '');
  if (message) return new Error(message);

  try {
    return new Error(JSON.stringify(thrown));
  } catch {
    return new Error(String(thrown));
  }
};

export function useGameMutation(
  config: GameMutationConfig,
): UseMutationResult {
  const { t } = useTranslation();
  const { setGlobalFeedback, addGlobalToast } = useRoomActions();

  const {
    mutationFn,
    successMessage,
    successTitle,
    successToast,
    successIcon,
    errorTitle,
    dispatchErrorFeedback = true,
    feedbackTtl = DEFAULT_FEEDBACK_TTL,
    onMutate,
    onSuccess,
    onError,
    onSettled,
  } = config;

  return useMutation({
    mutationFn: async (vars) => {
      let result: Result;

      try {
        result = await mutationFn(vars);
      } catch (thrown) {
        throw toError(thrown);
      }

      if (!result.isSuccess) {
        // Phase 2 Amendment: the error is flattened to a string *here*, at the
        // throw site, so that every downstream consumer -- onError included --
        // can treat `error.message` as a plain string.
        throw new Error(
          typeof result.errorMessage === 'string'
            ? result.errorMessage
            : JSON.stringify(result.errorMessage),
        );
      }

      return result.value;
    },

    onMutate,

    onSuccess: (data, vars, context) => {
      if (successMessage) {
        const resolvedMessage = t(successMessage);
        const resolvedTitle = t(successTitle ?? successMessage);

        if (successToast) {
          addGlobalToast({
            type: successToast,
            title: resolvedTitle,
            message: resolvedMessage,
            icon: successIcon ?? '',
          });
        } else {
          setGlobalFeedback({ type: 'success', title: resolvedTitle, message: resolvedMessage });
          setTimeout(() => setGlobalFeedback(null), feedbackTtl);
        }
      }

      onSuccess?.(data, vars, context);
    },

    onError: (error, vars, context) => {
      if (dispatchErrorFeedback) {
        // Phase 2 Amendment: `error` is always a real `Error` by this point,
        // so `error.message` is the flattened string -- no nested-object digging.
        setGlobalFeedback({
          type: 'error',
          title: errorTitle ? t(errorTitle) : t(DEFAULT_ERROR_TITLE_KEY),
          message: getSafeString(error.message, t(DEFAULT_ERROR_TITLE_KEY)),
        });
      }

      onError?.(error, vars, context);
    },

    onSettled,
  });
}

import { useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import { joinRoom, fetchRoomState } from '@/services/api';
import { getSafeStringStorage, setSafeStringStorage } from '@/utils/storage';
import type { GameRoom, Evidence, Character } from '@/types';

export function useGameRoom(inviteCode: string | undefined) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const {
    data: room,
    isLoading,
    error,
    refetch
  } = useQuery({
    queryKey: ['gameRoom', inviteCode],
    queryFn: async () => {
      if (!inviteCode) throw new Error(t('pages.gameRoom.noInviteCode'));

      // OPAQUE identifier, not structured data: kept as a bare string so the
      // reader below stays a plain parseInt. The JSON helpers would quote the
      // value on write and fail to parse it on read (and purge it). Writer and
      // reader must both stay raw -- see getSafeStringStorage in utils/storage.
      const storageKey = `active_room_id_for_${inviteCode}`;
      let roomId = getSafeStringStorage('session', storageKey, '');

      if (!roomId) {
        const joinResult = await joinRoom(inviteCode);
        if (!joinResult.isSuccess) throw new Error(joinResult.errorMessage);

        roomId = joinResult.value.id.toString();
      }

      const stateResult = await fetchRoomState(parseInt(roomId, 10));
      if (!stateResult.isSuccess) throw new Error(stateResult.errorMessage);

      return stateResult.value;
    },
    enabled: !!inviteCode,
  });

  useEffect(() => {
if (room?.id && inviteCode) {
        // Same opaque raw-string contract as the read above; the key template
        // is intentionally inlined rather than hoisted, matching the read site.
        setSafeStringStorage('session', `active_room_id_for_${inviteCode}`, room.id.toString());
      }
  }, [room?.id, inviteCode]);

  const patchRoomData = (updater: (oldRoom: GameRoom) => GameRoom) => {
    if (inviteCode) {
      queryClient.setQueryData(['gameRoom', inviteCode], (oldData: GameRoom | undefined) => {
        if (!oldData) return oldData;
        return updater(oldData);
      });
    }
  };

  const accumulatedEvidences: Evidence[] = room?.accumulated_evidences || [];
  const accumulatedCharacters: Character[] = room?.accumulated_characters || [];

  return {
    room,
    isLoading,
    error: error instanceof Error ? error.message : null,
    accumulatedEvidences,
    accumulatedCharacters,
    refreshRoomData: async () => { await refetch(); },
    patchRoomData
  };
}

import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { useRoomState, useRoomActions } from '@/context/RoomContext';
import { useGameMutation } from './useGameMutation';
import { getLocalUser } from '@/utils/userState';
import { getSafeString } from '@/utils/parsers';
import type { Choice } from '@/types';
import { lockVote, submitAssessment, initiatePhase, triggerWiretap } from '@/services/api';

export type { ToastNotification, GlobalFeedback } from '@/context/RoomContext';

export function useInvestigationPhase() {
  const { t } = useTranslation();
  const { room } = useRoomState();
  const { refreshRoomData, addGlobalToast, setGlobalFeedback } = useRoomActions();

  const [localVotes, setLocalVotes] = useState<Record>({});
  const roomId = room.id;

  useEffect(() => {
    const currentUser = getLocalUser();
    if (!currentUser) return;

    const serverVotes: Record = {};
    room.votes?.forEach((vote: any) => {
      if (vote.user_id === currentUser.id) {
        serverVotes[vote.question_id] = vote.choice_id;
      }
    });
    setLocalVotes(serverVotes);
  }, [room.votes]);

  const voteMutation = useGameMutation({
    mutationFn: ({ questionId, choiceId }: { questionId: number, choiceId: number }) =>
      lockVote(roomId, questionId, choiceId),
    onSuccess: () => refreshRoomData()
  });

  const submitTheoryMutation = useGameMutation({
    mutationFn: async () => {
      // STRICT GUARD
      if (room.current_level_id === null || room.current_level_id === undefined) {
        throw { message: 'No active level to submit.' };
      }

      return submitAssessment(roomId);
    },
    // The consensus outcome is branched on below, so the success dispatch is
    // left to `onSuccess` rather than the unified handler.
    errorTitle: 'pages.gameRoom.hooks.phase.systemError',
    onSuccess: (data) => {
      if (data.status === 'success' || data.status === 'failed_final') {
        setGlobalFeedback({
          type: data.status === 'success' ? 'success' : 'error',
          title: data.status === 'success' ? t('pages.gameRoom.hooks.phase.consensusVerified') : t('pages.gameRoom.hooks.phase.theoryRejected'),
          message: getSafeString(data.message, '')
        });

        // 1. UPDATE STATE IMMEDIATELY (Eliminates the 4-second block)
        setLocalVotes({});
        refreshRoomData();

        // 2. ONLY DELAY THE MODAL DISMISSAL
        setTimeout(() => {
          setGlobalFeedback(null);
        }, 4000);
      } else {
        setGlobalFeedback({
          type: 'error',
          title: t('pages.gameRoom.hooks.phase.theoryRejected'),
          message: getSafeString(data.message, t('pages.gameRoom.hooks.phase.systemError'))
        });
        setLocalVotes({});
        refreshRoomData();
      }
    }
  });

  const initiatePhaseMutation = useGameMutation({
    mutationFn: (levelId: number) => initiatePhase(roomId, levelId),
    errorTitle: 'pages.gameRoom.hooks.phase.systemError',
    onSuccess: () => refreshRoomData()
  });

  const triggerWiretapMutation = useGameMutation({
    mutationFn: ({ questionId }: { questionId: number, audioUrl: string }) => triggerWiretap(roomId, questionId),
    errorTitle: 'pages.gameRoom.hooks.phase.transmissionError',
    onSuccess: () => refreshRoomData()
  });

  // --- NEW: Safe Event Handling ---
  const handleSelectChoice = (e: React.MouseEvent | any, questionId: number, choice: Choice, status: string) => {
    if (e && typeof e.stopPropagation === 'function') e.stopPropagation();
    if (status !== 'active') return;

    setLocalVotes(prev => ({ ...prev, [questionId]: choice.id }));

    if (choice.outcomes?.unlock_evidence && choice.outcomes.unlock_evidence.length > 0) {
      addGlobalToast({
        type: 'evidence',
        title: t('pages.gameRoom.hooks.phase.evidenceRecovered'),
        message: t('pages.gameRoom.hooks.phase.evidenceRecoveredMsg', { count: choice.outcomes.unlock_evidence.length }),
        icon: 'https://api.iconify.design/ph:file-magnifying-glass-duotone.svg?color=%23c48b36'
      });
    }
    if (choice.outcomes?.unlock_levels && choice.outcomes.unlock_levels.length > 0) {
      addGlobalToast({
        type: 'level',
        title: t('pages.gameRoom.hooks.phase.phaseUnlocked'),
        message: t('pages.gameRoom.hooks.phase.phaseUnlockedMsg'),
        icon: 'https://api.iconify.design/ph:git-merge-duotone.svg?color=%235a8a9e'
      });
    }
    if (choice.outcomes?.character_updates && choice.outcomes.character_updates.length > 0) {
      choice.outcomes.character_updates.forEach((update: any) => {
        if (update.is_unlocked) {
          addGlobalToast({
            type: 'character', // Custom type for styling
            title: t('pages.gameRoom.hooks.phase.personOfInterest'),
            message: t('pages.gameRoom.hooks.phase.personOfInterestMsg'),
            icon: 'https://api.iconify.design/ph:user-focus-duotone.svg?color=%23a33232'
          });
        }
        if (update.status === 'deceased') {
          addGlobalToast({
            type: 'system',
            title: t('pages.gameRoom.hooks.phase.casualtyIdentified', 'Critical Update'),
            message: t('pages.gameRoom.hooks.phase.casualtyIdentifiedMsg', 'A person of interest has been confirmed deceased.'),
            icon: 'https://api.iconify.design/ph:skull-duotone.svg?color=%238a8d91'
          });
        }
      });
    }

    voteMutation.mutate({ questionId, choiceId: choice.id });
  };

  const handleSubmitTheory = useCallback((e?: React.MouseEvent | any) => {
    if (e && typeof e.stopPropagation === 'function') e.stopPropagation();

    // STRICT GUARD: Block submission entirely if the room has no active level currently in play
    if (room.current_level_id === null || room.current_level_id === undefined) {
      return;
    }

    submitTheoryMutation.mutate();
  }, [room.current_level_id, submitTheoryMutation]);

  const clearFeedback = (e?: React.MouseEvent | any) => {
    if (e && typeof e.stopPropagation === 'function') e.stopPropagation();
    setGlobalFeedback(null);
  };

  return {
    localVotes,
    isSubmitting: submitTheoryMutation.isPending || voteMutation.isPending,
    isInitiating: initiatePhaseMutation.isPending,
    handleSelectChoice,
    handleSubmitTheory,
    initiatePhase: (levelId: number) => initiatePhaseMutation.mutate(levelId),
    clearFeedback,
    triggerWiretap: (questionId: number, audioUrl: string) => triggerWiretapMutation.mutate({ questionId, audioUrl }),
    isTriggeringWiretap: triggerWiretapMutation.isPending,
    addToast: addGlobalToast
  };
}

import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import { submitInvestigationRequest } from '@/services/api';
import { useGameMutation } from './useGameMutation';
import type { GameRoom } from '@/types';
import type { ToastNotification } from './useInvestigationPhase';

export interface FiledRequest {
  id: number | string;
  request_type: string;
  created_at: string;
  evidence_ids: number[];
}

interface RequestRollback {
  previousRoom: unknown;
}

export function useInvestigationRequest(room: GameRoom, refreshRoomData: () => void) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const [trayEvidences, setTrayEvidences] = useState([]);
  const [requestType, setRequestType] = useState('');
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
  const [toasts, setToasts] = useState([]);

  // Derived directly from the authoritative room payload
  const filedRequests: FiledRequest[] = room.filed_requests || [];

  const requestMutation = useGameMutation<
    { status: string; message: string; unlocked_evidence: number[]; unlocked_levels?: number[] },
    void,
    RequestRollback
  >({
    mutationFn: () => submitInvestigationRequest(room.id, trayEvidences),
    // GameRoomLayout renders the request verdict in its own modal.
    dispatchErrorFeedback: false,
    onMutate: async () => {
      await queryClient.cancelQueries({ queryKey: ['gameRoom', room.invite_code] });
      const previousRoom = queryClient.getQueryData(['gameRoom', room.invite_code]);

      const optimisticRequest: FiledRequest = {
        id: `temp-${Date.now()}`,
        request_type: requestType,
        created_at: new Date().toISOString(),
        evidence_ids: [...trayEvidences]
      };

      queryClient.setQueryData(['gameRoom', room.invite_code], (old: any) => {
        if (!old) return old;
        return {
          ...old,
          filed_requests: [optimisticRequest, ...(old.filed_requests || [])]
        };
      });

      return { previousRoom };
    },
    onError: (error, _variables, context) => {
      queryClient.setQueryData(['gameRoom', room.invite_code], context?.previousRoom);
      setFeedback({ type: 'error', message: error.message });
      setTrayEvidences([]);
    },
    onSuccess: (data) => {
      setFeedback({ type: 'success', message: data.message });
      setTrayEvidences([]);
      setRequestType('');
      refreshRoomData();

      // Trigger respective toast notifications based on what the DA unlocked
      setTimeout(() => {
        const newToasts: ToastNotification[] = [];

        if (data.unlocked_evidence && data.unlocked_evidence.length > 0) {
          newToasts.push({
            id: crypto.randomUUID(),
            type: 'evidence',
            title: t('pages.gameRoom.hooks.request.proceduralApproved'),
            message: t('pages.gameRoom.hooks.request.proceduralApprovedMsg'),
            icon: 'https://api.iconify.design/ph:file-magnifying-glass-duotone.svg?color=%23c48b36'
          });
        }

        if (data.unlocked_levels && data.unlocked_levels.length > 0) {
          newToasts.push({
            id: crypto.randomUUID(),
            type: 'level',
            title: t('pages.gameRoom.hooks.request.warrantExecuted'),
            message: t('pages.gameRoom.hooks.request.warrantExecutedMsg'),
            icon: 'https://api.iconify.design/ph:git-merge-duotone.svg?color=%235a8a9e'
          });
        }

        if (newToasts.length > 0) {
          setToasts(prev => [...prev, ...newToasts]);
          setTimeout(() => {
            setToasts((prev) => prev.filter((t) => !newToasts.some((nt) => nt.id === t.id)));
          }, 5000);
        }
      }, 500);
    }
  });

  const addToTray = (evidenceId: number) => {
    if (!trayEvidences.includes(evidenceId)) {
      setTrayEvidences([...trayEvidences, evidenceId]);
    }
  };

  const removeFromTray = (evidenceId: number) => {
    setTrayEvidences(trayEvidences.filter(id => id !== evidenceId));
  };

  const clearFeedback = () => setFeedback(null);

  return {
    trayEvidences,
    requestType,
    setRequestType,
    addToTray,
    removeFromTray,
    isSubmitting: requestMutation.isPending,
    feedback,
    toasts,
    clearFeedback,
    submitRequest: requestMutation.mutate,
    filedRequests
  };
}

import { useState } from 'react';
import { submitSuspectVerdict } from '@/services/api';
import { getSafeStorage, setSafeStorage, clearRoomSessionData } from '@/utils/storage';
import { useGameMutation } from './useGameMutation';
import type { GameRoom } from '@/types';

export function useSuspectVerdict(room: GameRoom, refreshRoomData: () => void, setGameOverData: any) {
  const guiltyStorageKey = `room_${room.invite_code}_guilty_characters`;

  const [guiltyIds, setGuiltyIds] = useState(() =>
    getSafeStorage('session', guiltyStorageKey, [])
  );

  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  const verdictMutation = useGameMutation<{ status: string; message: string; stats?: unknown }, number[]>({
    mutationFn: (submittedGuiltyIds) => submitSuspectVerdict(room.id, submittedGuiltyIds),
    // The Characters tab renders its own indictment modal, so the global
    // overlay would just duplicate it.
    dispatchErrorFeedback: false,
    onSuccess: (data) => {
      if (data.status === 'failed') {
        setFeedback({ type: 'error', message: data.message });
        refreshRoomData();
      } else {
        clearRoomSessionData(room.id, room.invite_code);
        setGameOverData(data.message, data.stats);
        refreshRoomData();
      }
    },
    onError: (error) => {
      setFeedback({ type: 'error', message: error.message });
    }
  });

  const handleCharacterDrop = (characterId: number, targetPool: 'guilty' | 'unassigned') => {
    let nextGuilty = guiltyIds.filter(id => id !== characterId);
    if (targetPool === 'guilty') nextGuilty.push(characterId);

    setGuiltyIds(nextGuilty);
    setSafeStorage('session', guiltyStorageKey, nextGuilty);
  };

  const clearFeedback = () => {
    setFeedback(null);
    refreshRoomData();
  };

  return {
    guiltyIds,
    feedback,
    isSubmitting: verdictMutation.isPending,
    handleCharacterDrop,
    submitVerdict: () => verdictMutation.mutate(guiltyIds),
    clearFeedback
  };
}

import { useState, useCallback, useEffect } from 'react';
import { getSafeStorage, setSafeStorage } from '@/utils/storage';

type TrackableEntity = 'evidence' | 'characters' | 'locations';

const readViewed = (storageKey: string): Set => {
  return new Set(getSafeStorage('session', storageKey, []));
};

export function useViewedItems(roomKey: string | number | undefined, entityType: TrackableEntity) {
  const storageKey = roomKey ? `room_${roomKey}_viewed_${entityType}` : null;

  const [viewedItems, setViewedItems] = useState<Set>(() => {
    if (!storageKey) return new Set();
    return readViewed(storageKey);
  });

  useEffect(() => {
    if (!storageKey) return;
    setViewedItems(readViewed(storageKey));
  }, [storageKey]);

  const markItemAsViewed = useCallback((id: number) => {
    if (!storageKey) return;

    setViewedItems(prev => {
      if (prev.has(id)) return prev;

      const nextViewed = new Set(prev);
      nextViewed.add(id);

      setSafeStorage('session', storageKey, Array.from(nextViewed));

      return nextViewed;
    });
  }, [storageKey]);

  return { viewedItems, markItemAsViewed };
}

