import { useState, useEffect, useRef, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useRoomState } from '@/context/RoomContext';
import { useInvestigationPhase } from '@/hooks/useInvestigationPhase';
import { getSafeStorage, setSafeStorage } from '@/utils/storage';
import type { Level, Choice, Question } from '@/types';
import interrogationPhase from './InterrogationPhase.module.css';

// --- MESSAGE REVEAL COMPONENT ---
const MessageReveal = ({ text, onComplete, skip = false, cacheKey = '' }: { text: string, delay?: number, onComplete?: () => void, skip?: boolean, cacheKey?: string }) => {
  const [isTyping, setIsTyping] = useState(!skip && !(cacheKey && getSafeStorage('session', cacheKey, false)));
  const savedOnComplete = useRef(onComplete);

  useEffect(() => {
    savedOnComplete.current = onComplete;
  }, [onComplete]);

  useEffect(() => {
    if (!text) {
      if (savedOnComplete.current) savedOnComplete.current();
      return;
    }

    if (!isTyping) {
      if (savedOnComplete.current) savedOnComplete.current();
      return;
    }

    // Dynamic delay based on text length (min 800ms, max 2500ms) for realism
    const calculatedDelay = Math.min(Math.max(text.length * 15, 800), 2500);

    const timer = setTimeout(() => {
      setIsTyping(false);
      if (cacheKey) setSafeStorage('session', cacheKey, true);
    }, calculatedDelay);

    return () => clearTimeout(timer);
  }, [isTyping, text, cacheKey]);

  if (isTyping) {
    return (



    );
  }

  return {text};
};

interface InterrogationPhaseProps {
  level: Level;
  status: string;
  totalPlayers: number;
  getQuestionConsensus: (question: Question) => { votesCast: number, isResolved: boolean, isTie: boolean, winningChoiceId: number | null };
  isHost: boolean;
  isSubmitting: boolean;
  handleSubmitTheory: (e?: React.MouseEvent) => void;
}

export default function InterrogationPhase({
  level, status, totalPlayers, getQuestionConsensus, isHost, isSubmitting, handleSubmitTheory
}: InterrogationPhaseProps) {
  const { t } = useTranslation();
  const { room, accumulatedEvidences } = useRoomState();
  const { localVotes, handleSelectChoice } = useInvestigationPhase();

  const checkIsLockedByNarrative = (choice: Choice) => {
    if (!choice.requirements) return false;
    const reqs = choice.requirements;

    if (reqs.required_evidence?.length > 0) {
      const hasAllEvidence = reqs.required_evidence.every((id: number) =>
        accumulatedEvidences.some(e => e.id === id)
      );
      if (!hasAllEvidence) return true;
    }

    if (reqs.required_choices?.length > 0) {
      const hasAllChoices = reqs.required_choices.every((id: number) =>
        room.votes?.some(v => v.choice_id === id)
      );
      if (!hasAllChoices) return true;
    }

    return false;
  };

  const [suspectTypingComplete, setSuspectTypingComplete] = useState<Record>(() => {
    const initial: Record = {};
    level.questions?.forEach(q => {
      if (getSafeStorage('session', `room_${room.id}_suspect_${q.id}`, false)) initial[q.id] = true;
    });
    return initial;
  });

  const [investigatorTypingComplete, setInvestigatorTypingComplete] = useState<Record>(() => {
    const initial: Record = {};
    level.questions?.forEach(q => {
      if (getSafeStorage('session', `room_${room.id}_investigator_${q.id}`, false)) initial[q.id] = true;
    });
    return initial;
  });

  const { visibleQuestions, consensusMap } = useMemo(() => {
    const questions: Question[] = [];
    const map: Record<number, ReturnType> = {};

    if (!level.questions || level.questions.length === 0) {
      return { visibleQuestions: questions, consensusMap: map };
    }

    let currentId: number | null = level.questions[0].id;

    while (currentId) {
      const q = level.questions.find(x => x.id === currentId);
      if (!q) break;
      questions.push(q);

      const consensus = getQuestionConsensus(q);
      map[q.id] = consensus;

      if (consensus.isResolved && consensus.winningChoiceId) {
        const winningChoice = q.choices?.find(c => c.id === consensus.winningChoiceId);

        if (winningChoice?.outcomes?.next_question_id) {
          currentId = Number(winningChoice.outcomes.next_question_id);
        } else {
          currentId = null;
        }
      } else {
        currentId = null;
      }
    }
    return { visibleQuestions: questions, consensusMap: map };
    // `react-hooks/exhaustive-deps` flags `room.votes` as unnecessary here.
    // That warning was traced and is a false positive: getQuestionConsensus is
    // an inline function in CampaignTab.tsx that reads room.votes, so it gets a
    // new identity every render and the memo recomputes regardless. Dropping
    // `room.votes` from this list would not avoid the recomputation -- it would
    // only hide the real dependency behind a changing function reference.
    // Leave the array as-is.
  }, [level.questions, room.votes, getQuestionConsensus]);

  const handleSuspectDone = (qId: number) => setSuspectTypingComplete(prev => ({ ...prev, [qId]: true }));
  const handleInvestigatorDone = (qId: number) => setInvestigatorTypingComplete(prev => ({ ...prev, [qId]: true }));

  const lastQuestion = visibleQuestions[visibleQuestions.length - 1];
  const hasNoChoices = !lastQuestion?.choices || lastQuestion.choices.length === 0;

  const lastConsensus = lastQuestion ? consensusMap[lastQuestion.id] : null;
  const finalWinningChoice = lastConsensus?.winningChoiceId
    ? lastQuestion.choices?.find(c => c.id === lastConsensus.winningChoiceId)
    : null;
  const isPlayerTerminal = lastConsensus?.isResolved && finalWinningChoice && !finalWinningChoice?.outcomes?.next_question_id;

  const isTerminalNode = hasNoChoices || isPlayerTerminal;

  const isReadyToSubmit = lastQuestion && (
    hasNoChoices
      ? (suspectTypingComplete[lastQuestion.id] || status === 'completed')
      : (investigatorTypingComplete[lastQuestion.id] || status === 'completed')
  );

  // 1. ADD THIS: A strict local lock to prevent double-firing
  const hasAutoSubmitted = useRef(false);

  // 2. ADD THIS: Reset the lock if the level status safely changes
  useEffect(() => {
    if (status !== 'active') {
      hasAutoSubmitted.current = false;
    }
  }, [status]);

  // 3. UPDATE THIS: Add the ref check to your existing trigger
  useEffect(() => {
    if (status === 'active' && isTerminalNode && isReadyToSubmit && isHost && !isSubmitting && !hasAutoSubmitted.current) {
      hasAutoSubmitted.current = true; // Lock it immediately
      handleSubmitTheory();
    }
  }, [status, isTerminalNode, isReadyToSubmit, isHost, isSubmitting, handleSubmitTheory]);

  if (visibleQuestions.length === 0) return null;

  return (


      {visibleQuestions.map((q, qIdx) => {
        const consensus = consensusMap[q.id];
        const prevQ = qIdx > 0 ? visibleQuestions[qIdx - 1] : null;
        const isVisible = status === 'completed' || qIdx === 0 || (prevQ && investigatorTypingComplete[prevQ.id]);

        if (!isVisible) return null;

        const isGloballyLocked = consensus.isResolved;
        const skipTyping = status === 'completed';
        const isSuspectDone = suspectTypingComplete[q.id] || skipTyping;
        const hasLocalVote = !!localVotes[q.id];

        const winningChoice = q.choices?.find(c => c.id === consensus.winningChoiceId);
        const customReaction = winningChoice?.outcomes?.suspect_reaction;

        return (






                {t('pages.gameRoom.campaign.levels.interrogation.suspect')} {customReaction ? `[${customReaction}]` : ''}



                 handleSuspectDone(q.id)}
                />



            {isSuspectDone && q.choices && q.choices.length > 0 && (
              <>
                {status === 'active' && !isGloballyLocked && (





                        {consensus.isTie
                          ? t('pages.gameRoom.campaign.levels.interrogation.tieDetected')
                          : hasLocalVote
                            ? t('pages.gameRoom.campaign.levels.interrogation.voteCast', { votes: consensus.votesCast, total: totalPlayers })
                            : t('pages.gameRoom.campaign.levels.interrogation.selectResponse', { votes: consensus.votesCast, total: totalPlayers })
                        }



                        {q.choices?.map(c => {
                          const isSelected = localVotes[q.id] === c.id;
                          const isNarrativeLocked = checkIsLockedByNarrative(c);
                          const pillClass = isNarrativeLocked
                            ? `choice-pill ${interrogationPhase['locked-choice']}`
                            : `choice-pill interactable ${isSelected ? 'selected' : ''}`;

                          return (
                             {
                                if (isNarrativeLocked || status !== 'active') return;
                                handleSelectChoice(e, q.id, c, status);
                              }}
                              style={{ padding: '0.75rem 1rem', fontSize: '0.9rem' }}
                            >
                              {isNarrativeLocked ? t('pages.gameRoom.campaign.levels.interrogation.missingIntel') : c.text}

                          );
                        })}



                )}

                {isGloballyLocked && winningChoice && (




                      {t('pages.gameRoom.campaign.levels.interrogation.investigators')}


                         handleInvestigatorDone(q.id)}
                        />



                )}
              </>
            )}

        );
      })}

  );
}

import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useTranslation } from 'react-i18next';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useRoomState } from '@/context/RoomContext';
import { useInvestigationPhase } from '@/hooks/useInvestigationPhase';
import { getLocalUser } from '@/utils/userState';
import { getSafeStorage, setSafeStorage } from '@/utils/storage';
import type { Level, Choice } from '@/types';
import * as api from '@/services/api';
import locationPhase from './LocationPhase.module.css';

interface LocationPhaseProps {
  level: Level;
  isHost: boolean;
}

export default function LocationPhase({ level }: LocationPhaseProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { room, accumulatedEvidences } = useRoomState();
  const { localVotes, handleSelectChoice, addToast } = useInvestigationPhase();

  const currentUserId = getLocalUser()?.id;

  const checkIsLockedByNarrative = (choice: Choice) => {
    if (!choice.requirements) return false;
    const reqs = choice.requirements;

    if (reqs.required_evidence?.length > 0) {
      const hasAllEvidence = reqs.required_evidence.every((id: number) =>
        accumulatedEvidences.some(e => e.id === id)
      );
      if (!hasAllEvidence) return true;
    }

    if (reqs.required_choices?.length > 0) {
      const hasAllChoices = reqs.required_choices.every((id: number) =>
        room.votes?.some(v => v.choice_id === id)
      );
      if (!hasAllChoices) return true;
    }

    return false;
  };

  const [inspectingQuestionId, setInspectingQuestionId] = useState(null);

  // --- ZOOM & PAN STATE ---
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [lastMouse, setLastMouse] = useState({ x: 0, y: 0 });

  const wrapperRef = useRef(null);

  const storageKeyBase = `inv_loc_state_${room.id}_${level.id}`;

  const [localFound, setLocalFound] = useState<Set>(() => {
    return new Set(getSafeStorage('local', `${storageKeyBase}_found`, []));
  });

  const [localDeadEnds, setLocalDeadEnds] = useState<Set>(() => {
    return new Set(getSafeStorage('local', `${storageKeyBase}_deadEnds`, []));
  });

  const [activeBubbles, setActiveBubbles] = useState<Set>(() => {
    return new Set(getSafeStorage('local', `${storageKeyBase}_bubbles`, []));
  });

  useEffect(() => {
    setSafeStorage('local', `${storageKeyBase}_found`, Array.from(localFound));
  }, [localFound, storageKeyBase]);

  useEffect(() => {
    setSafeStorage('local', `${storageKeyBase}_deadEnds`, Array.from(localDeadEnds));
  }, [localDeadEnds, storageKeyBase]);

  useEffect(() => {
    setSafeStorage('local', `${storageKeyBase}_bubbles`, Array.from(activeBubbles));
  }, [activeBubbles, storageKeyBase]);

  const foundPoints = new Set([
    ...(room.inspections?.filter((i: any) => !i.is_dead_end).map((i: any) => i.choice_id) || []),
    ...localFound
  ]);
  const clickedDeadEnds = new Set([
    ...(room.inspections?.filter((i: any) => i.is_dead_end).map((i: any) => i.choice_id) || []),
    ...localDeadEnds
  ]);

  const inspectMutation = useMutation({
    mutationFn: async (choiceId: number) => {
      const result = await api.inspectLocation(room.id, choiceId);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onMutate: async (choiceId) => {
      await queryClient.cancelQueries({ queryKey: ['gameRoom', room.invite_code] });
      const previousRoom = queryClient.getQueryData(['gameRoom', room.invite_code]);

      queryClient.setQueryData(['gameRoom', room.invite_code], (old: any) => {
        if (!old) return old;

        let isCorrectFind = false;
        level.questions?.forEach(q => {
          const c = q.choices?.find(x => x.id === choiceId);
          if (c) {
            isCorrectFind = !!(c.outcomes?.next_question_id || c.outcomes?.unlock_evidence?.length || c.outcomes?.unlock_levels?.length || c.outcomes?.unlock_suspects?.length || c.outcomes?.unlock_victims?.length);
          }
        });

        return {
          ...old,
          inspections: [...(old.inspections || []), { choice_id: choiceId, is_dead_end: !isCorrectFind }]
        };
      });

      return { previousRoom };
    },
    onError: (_error, _variables, context) => {
      queryClient.setQueryData(['gameRoom', room.invite_code], context?.previousRoom);
    }
  });

  if (!level.questions) return null;

  const visibleQuestionIds = new Set();

  const lockedBehindChoiceIds = new Set();
  level.questions.forEach(q => {
    q.choices?.forEach(c => {
      if (c.outcomes?.next_question_id) {
        lockedBehindChoiceIds.add(Number(c.outcomes.next_question_id));
      }
    });
  });

  level.questions.forEach(q => {
    if (!lockedBehindChoiceIds.has(q.id)) {
      visibleQuestionIds.add(q.id);
    }
  });

  level.questions.forEach(q => {
    q.choices?.forEach(c => {
      const isSelectedLocally = foundPoints.has(c.id) || localVotes[q.id] === c.id;
      const isSelectedGlobally = room.votes?.some(v => v.choice_id === c.id);

      if (isSelectedLocally || isSelectedGlobally) {
        if (c.outcomes?.next_question_id) {
          visibleQuestionIds.add(Number(c.outcomes.next_question_id));
        }
      }
    });
  });

  const displayQuestions = level.questions.filter(q =>
    visibleQuestionIds.has(q.id) &&
    (q.assigned_user_id === currentUserId ||
     q.assigned_user_id === undefined ||
     q.assigned_user_id === null)
  );

  const handlePointClick = (e: React.MouseEvent, qId: number, choice: Choice) => {
    e.stopPropagation();

    if (isDragging) return;

    const isAlreadyDiscovered = foundPoints.has(choice.id) || clickedDeadEnds.has(choice.id) || room.votes?.some((v: any) => v.choice_id === choice.id);

    if (isAlreadyDiscovered) {
      setActiveBubbles(prev => {
        const next = new Set(prev);
        if (next.has(choice.id)) next.delete(choice.id);
        else next.add(choice.id);
        return next;
      });
      return;
    }

    const hasUnlocks = choice.outcomes && (
      (choice.outcomes.unlock_evidence && choice.outcomes.unlock_evidence.length > 0) ||
      (choice.outcomes.unlock_levels && choice.outcomes.unlock_levels.length > 0) ||
      (choice.outcomes.unlock_suspects && choice.outcomes.unlock_suspects.length > 0) ||
      (choice.outcomes.unlock_victims && choice.outcomes.unlock_victims.length > 0) ||
      (choice.outcomes.next_question_id)
    );

    const isCorrectFind = !!hasUnlocks;

    if (isCorrectFind) {
      setLocalFound(prev => new Set(prev).add(choice.id));
    } else {
      setLocalDeadEnds(prev => new Set(prev).add(choice.id));
    }

    setActiveBubbles(prev => new Set(prev).add(choice.id));
    inspectMutation.mutate(choice.id);

    if (isCorrectFind) {
      if (choice.outcomes?.next_question_id) {
        addToast({
          type: 'level',
          title: t('pages.gameRoom.campaign.levels.location.newSceneUnlocked'),
          message: t('pages.gameRoom.campaign.levels.location.newVantagePoint'),
          icon: 'https://api.iconify.design/ph:map-pin-line-duotone.svg?color=%235a8a9e'
        });
      }
      handleSelectChoice(e, qId, choice, 'active');
    }
  };

  const closeViewer = () => {
    setInspectingQuestionId(null);
    setScale(1);
    setPosition({ x: 0, y: 0 });
  };

  const clampPosition = (targetX: number, targetY: number, currentScale: number) => {
    if (!wrapperRef.current) return { x: targetX, y: targetY };

    const { clientWidth, clientHeight } = wrapperRef.current;

    const maxX = Math.max(0, (clientWidth * currentScale - window.innerWidth) / 2);
    const maxY = Math.max(0, (clientHeight * currentScale - window.innerHeight) / 2);

    return {
      x: Math.min(Math.max(targetX, -maxX), maxX),
      y: Math.min(Math.max(targetY, -maxY), maxY)
    };
  };

  const handleWheel = (e: React.WheelEvent) => {
    const zoomSensitivity = 0.005;
    const delta = e.deltaY * -zoomSensitivity;
    const newScale = Math.min(Math.max(1, scale + delta), 5);

    setScale(newScale);

    if (newScale === 1) {
      setPosition({ x: 0, y: 0 });
    } else {
      setPosition(prev => clampPosition(prev.x, prev.y, newScale));
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (scale > 1) {
      setIsDragging(true);
      setLastMouse({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDragging && scale > 1) {
      const deltaX = e.clientX - lastMouse.x;
      const deltaY = e.clientY - lastMouse.y;

      const newX = position.x + deltaX;
      const newY = position.y + deltaY;

      setPosition(clampPosition(newX, newY, scale));
      setLastMouse({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseUp = () => setIsDragging(false);

  const activeQuestion = displayQuestions.find(q => q.id === inspectingQuestionId);

  const fullScreenViewer = activeQuestion ? createPortal(



        ✕



 1 ? 'grab' : 'auto') }}
      >




          {activeQuestion.choices?.map(choice => {
            const parts = choice.text.split('|');
            if (parts.length < 2) return null;

            const coords = parts[0].trim();
            const title = parts[1].trim();
            const coordParts = coords.split(',');
            if (coordParts.length < 2) return null;

            const x = coordParts[0].trim();
            const y = coordParts[1].trim();

            const hasUnlocks = choice.outcomes && (
              (choice.outcomes.unlock_evidence && choice.outcomes.unlock_evidence.length > 0) ||
              (choice.outcomes.unlock_levels && choice.outcomes.unlock_levels.length > 0) ||
              (choice.outcomes.unlock_suspects && choice.outcomes.unlock_suspects.length > 0) ||
              (choice.outcomes.unlock_victims && choice.outcomes.unlock_victims.length > 0) ||
              (choice.outcomes.next_question_id)
            );
            const isCorrectFind = !!hasUnlocks;

            const isSelected = localVotes[activeQuestion.id] === choice.id || foundPoints.has(choice.id) || room.votes?.some((v: any) => v.choice_id === choice.id);
            const isDeadEndClicked = clickedDeadEnds.has(choice.id);

            // STRICT FILTER CHECK
            const isNarrativeLocked = checkIsLockedByNarrative(choice);
            const isDiscovered = isSelected || isDeadEndClicked;

            let zoneClass = locationPhase['loc-hover-zone'];
            if (isSelected) {
              zoneClass += ` ${locationPhase['selected']}`;
            } else if (isDeadEndClicked || isNarrativeLocked) {
              zoneClass += ` ${locationPhase['investigated']}`;
            }

            const isBubbleActive = activeBubbles.has(choice.id);

            // If the element does not meet evidence prerequisites, it completely vanishes
            const isInteractable = !isNarrativeLocked || isDiscovered;
            const shouldRender = !isNarrativeLocked || isDiscovered;

            return (

 e.stopPropagation()}
                onClick={(e) => {
                  if (!isInteractable) return;
                  handlePointClick(e, activeQuestion.id, choice);
                }}
              >



                {!isBubbleActive && (


                    {isNarrativeLocked ? t('pages.gameRoom.campaign.levels.location.requiresIntel') : title}

                )}

                {isBubbleActive && (


                    {choice.outcomes?.feedback || (isCorrectFind ? t('pages.gameRoom.campaign.levels.location.foundUseful') : t('pages.gameRoom.campaign.levels.location.nothingFound'))}

                )}

            );
          })}


    ,
    document.body
  ) : null;

  return (


      {displayQuestions.map(q => (






               setInspectingQuestionId(q.id)}
                style={{ flex: 'none', width: 'auto', padding: '0.75rem 2rem', borderRadius: '50px', boxShadow: '0 4px 15px rgba(0,0,0,0.5)' }}
              >
                👁️ {t('pages.gameRoom.campaign.levels.location.inspectLocation')}




{q.text || t('pages.gameRoom.campaign.levels.location.enterViewerHint')}

      ))}

      {fullScreenViewer}

  );
}

import { useTranslation } from 'react-i18next';
import { useRoomState } from '@/context/RoomContext';
import { useInvestigationPhase } from '@/hooks/useInvestigationPhase';
import type { Level, Choice, Question } from '@/types';
import wiretapPhase from './WiretapPhase.module.css';

interface WiretapPhaseProps {
  level: Level;
  status: string;
  totalPlayers: number;
  getQuestionConsensus: (question: Question) => { votesCast: number, isResolved: boolean, isTie: boolean, winningChoiceId: number | null };
  isHost: boolean;
  isSubmitting: boolean;
  handleSubmitTheory: (e: React.MouseEvent) => void;
}

export default function WiretapPhase({
  level, status, totalPlayers, getQuestionConsensus, isHost, isSubmitting, handleSubmitTheory
}: WiretapPhaseProps) {
  const { t } = useTranslation();
  const { room, accumulatedEvidences } = useRoomState();
  const { localVotes, handleSelectChoice, triggerWiretap, isTriggeringWiretap } = useInvestigationPhase();

  const playedWiretaps = new Set(room.played_wiretaps?.map((q: any) => q.id) || []);

  const checkIsLockedByNarrative = (choice: Choice) => {
    if (!choice.requirements) return false;
    const reqs = choice.requirements;

    if (reqs.required_evidence?.length > 0) {
      const hasAllEvidence = reqs.required_evidence.every((id: number) =>
        accumulatedEvidences.some(e => e.id === id)
      );
      if (!hasAllEvidence) return true;
    }

    if (reqs.required_choices?.length > 0) {
      const hasAllChoices = reqs.required_choices.every((id: number) =>
        room.votes?.some(v => v.choice_id === id)
      );
      if (!hasAllChoices) return true;
    }

    return false;
  };

  if (!level.questions || level.questions.length === 0) return null;

  const visibleQuestions: Question[] = [];
  let currentId: number | null = level.questions[0].id;

  while (currentId) {
    const q = level.questions.find(x => x.id === currentId);
    if (!q) break;
    visibleQuestions.push(q);

    const consensus = getQuestionConsensus(q);
    if (consensus.isResolved && consensus.winningChoiceId) {
      const winningChoice = q.choices?.find(c => c.id === consensus.winningChoiceId);

      if (winningChoice?.outcomes?.next_question_id) {
        currentId = Number(winningChoice.outcomes.next_question_id);
      } else {
        const currentIndex = level.questions.findIndex(x => x.id === q.id);
        currentId = level.questions[currentIndex + 1]?.id || null;
      }
    } else {
      currentId = null;
    }
  }

  const requiredAudios = level.questions?.filter(q => q.audio_url) || [];
  const allAudiosPlayed = requiredAudios.length === 0 || requiredAudios.every(q => playedWiretaps.has(q.id));

  return (




        {t('pages.gameRoom.campaign.levels.wiretap.activeIntercept')}




        {visibleQuestions.map((q, qIdx) => {

          const consensus = getQuestionConsensus(q);
          const prevConsensus = qIdx > 0 ? getQuestionConsensus(visibleQuestions[qIdx - 1]) : null;

          const isVisible = status === 'completed' || qIdx === 0 || (prevConsensus && prevConsensus.isResolved);
          if (!isVisible) return null;

          const isLocked = consensus.isResolved;
          const hasLocalVote = !!localVotes[q.id];
          const hasBeenPlayed = playedWiretaps.has(q.id);
          const isAudioIntercept = !!q.audio_url;

          const interceptNumber = String(qIdx + 1).padStart(2, '0');

          return (





                {t('pages.gameRoom.campaign.levels.wiretap.interceptPrefix')}{interceptNumber}
                {isAudioIntercept && !hasBeenPlayed && (
                  🎙️
                )}
                {isAudioIntercept && hasBeenPlayed && (
                  🔇
                )}






                  {q.text}
                  {status === 'active' && !isLocked && (

                      {consensus.isTie
                          ? t('pages.gameRoom.campaign.levels.wiretap.tieDetected')
                          : hasLocalVote
                            ? t('pages.gameRoom.campaign.levels.wiretap.voteRecorded', { votes: consensus.votesCast, total: totalPlayers })
                            : t('pages.gameRoom.campaign.levels.wiretap.awaitingConsensus', { votes: consensus.votesCast, total: totalPlayers })
                        }

                  )}


                {isAudioIntercept && (


                    {hasBeenPlayed ? (


                        🔒
                        {t('pages.gameRoom.campaign.levels.wiretap.connectionSevered')}

                    ) : (
                       { e.stopPropagation(); triggerWiretap(q.id, q.audio_url!); }}
                      >
                        {isHost ? t('pages.gameRoom.campaign.levels.wiretap.initiateAudio') : t('pages.gameRoom.campaign.levels.wiretap.awaitingHostAudio')}

                    )}

                )}



                  {q.choices?.map(c => {
                    const isSelected = localVotes[q.id] === c.id;
                    const isHistoricalCorrect = status === 'completed' && !c.outcomes?.gives_strike;
                    const isNarrativeLocked = checkIsLockedByNarrative(c);

                    let pillClass = 'choice-pill';
                    if (isNarrativeLocked) {
                      pillClass = `choice-pill ${wiretapPhase['locked-choice']}`;
                    } else {
                      if (isSelected) pillClass += ' selected';
                      if (isHistoricalCorrect) pillClass += ' historical-correct';
                      if (status === 'active' && !isLocked && (!isAudioIntercept || hasBeenPlayed)) pillClass += ' interactable';
                    }

                    const preventGuessing = (isAudioIntercept && !hasBeenPlayed) || isNarrativeLocked;

                    return (
                       {
                          if (status === 'active' && !isLocked && !preventGuessing) handleSelectChoice(e, q.id, c, status);
                        }}
                      >
                        {isNarrativeLocked
                          ? t('pages.gameRoom.campaign.levels.wiretap.pathLocked')
                          : (isAudioIntercept && !hasBeenPlayed)
                            ? t('pages.gameRoom.campaign.levels.wiretap.classified')
                            : c.text
                        }

                    );
                  })}



          );
        })}


      {status === 'active' && (


          {isHost ? (

              {isSubmitting ? t('pages.gameRoom.campaign.levels.wiretap.processing') : t('pages.gameRoom.campaign.levels.wiretap.submitAnalysis')}

          ) : (


              {t('pages.gameRoom.campaign.levels.wiretap.awaitingHostSubmit')}

          )}

      )}

  );
}

