import type { DocDocument } from '@/types/evidence/doc';
import { DOC_TEMPLATES, resetTemplateSeq } from './templates';

/** Build a DocDocument from a template key. */
export const buildTemplate = (key: string): DocDocument | undefined => {
  const template = DOC_TEMPLATES.find(t => t.key === key);
  return template?.build();
};

/** All available template keys. */
export type TemplateName = 'correspondence' | 'financial_record' | 'journal' | 'contract' | 'memo' | 'background_check' | 'phone_records' | 'autopsy' | 'ballistics' | 'dna' | 'digital_forensics' | 'trace_analysis';

/** Map of template builders for the admin palette. */
export const templates: Record DocDocument> = {
  correspondence: () => buildTemplate('correspondence')!,
  financial_record: () => buildTemplate('financial_record')!,
  journal: () => buildTemplate('journal')!,
  contract: () => buildTemplate('contract')!,
  memo: () => buildTemplate('memo')!,
  background_check: () => buildTemplate('background_check')!,
  phone_records: () => buildTemplate('phone_records')!,
  autopsy: () => buildTemplate('autopsy')!,
  ballistics: () => buildTemplate('ballistics')!,
  dna: () => buildTemplate('dna')!,
  digital_forensics: () => buildTemplate('digital_forensics')!,
  trace_analysis: () => buildTemplate('trace_analysis')!,
};

export { resetTemplateSeq };

import type {
  DocBlock,
  DocDocument,
  DocTheme,
  MetaRow,
  TableColumn,
  TableRow,
} from '@/types/evidence/doc';
import { DEFAULT_PAGE } from '@/types/evidence/doc';

/**
 * Starter documents for the admin builder.
 *
 * Twelve templates, one per artefact the legacy document/forensic viewers used
 * to special-case, so an author can reproduce a familiar artefact without
 * rebuilding it block by block. Each factory returns a FRESH block tree on
 * every call -- templates are never shared by reference, because the
 * builder mutates blocks in place and a shared template would bleed edits across
 * every new document.
 *
 * Text is deliberately Latin/English placeholder. The game's content is
 * Arabic-first, and hardcoding Arabic strings here would put untranslated copy in
 * the codebase; the Phase 3 builder supplies real localized strings.
 */

let seq = 0;
/** Stable, collision-free id for template-authored blocks. */
const tid = (tag: string): string => {
  seq += 1;
  return `tpl_${tag}_${seq.toString(36)}`;
};

const letterhead = (
  agency: string,
  title: string,
  sub?: string,
  aside?: string,
  asideLabel?: string,
  span = 12,
): DocBlock => ({
  id: tid('lh'),
  type: 'letterhead',
  span,
  props: { agency, title, sub, aside, asideLabel, rule: true },
});

const meta = (
  rows: MetaRow[],
  opts?: { span?: number; columns?: number; tone?: 'rows' | 'boxed' | 'plain' },
): DocBlock => ({
  id: tid('meta'),
  type: 'meta_grid',
  span: opts?.span ?? 12,
  props: { rows, columns: opts?.columns ?? 2, tone: opts?.tone ?? 'rows' },
});

const prose = (html: string, tone?: 'typed' | 'handwritten' | 'mono' | 'serif', span = 12): DocBlock => ({
  id: tid('prose'),
  type: 'prose',
  span,
  props: { html, tone: tone ?? 'typed' },
});

const rule = (span = 12, variant?: 'solid' | 'dashed' | 'dotted' | 'double'): DocBlock => ({
  id: tid('rule'),
  type: 'rule',
  span,
  props: { variant },
});

const spacer = (height: number, span = 12): DocBlock => ({
  id: tid('sp'),
  type: 'spacer',
  span,
  props: { height },
});

const stamp = (text: string, tone?: 'official' | 'forged' | 'confidential' | 'crimson'): DocBlock => ({
  id: tid('st'),
  type: 'stamp',
  span: 4,
  props: { text, tone: tone ?? 'official' },
  style: { align: 'end' },
});

const watermark = (text: string): DocBlock => ({
  id: tid('wm'),
  type: 'watermark',
  span: 12,
  props: { text, rotate: -30 },
});

const table = (
  caption: string | undefined,
  columns: TableColumn[],
  rows: TableRow[],
  opts?: { tone?: 'ledger' | 'log'; span?: number; emptyMessage?: string },
): DocBlock => ({
  id: tid('tbl'),
  type: 'table',
  span: opts?.span ?? 12,
  props: {
    columns,
    rows,
    tone: opts?.tone ?? 'ledger',
    caption,
    emptyMessage: opts?.emptyMessage,
  },
});

const list = (items: string[], ordered = false, span = 12): DocBlock => ({
  id: tid('li'),
  type: 'list',
  span,
  props: { items, ordered },
});

const doc = (theme: DocTheme, blocks: DocBlock[]): DocDocument => ({
  v: 1,
  theme,
  page: { ...DEFAULT_PAGE },
  blocks,
});

export interface DocTemplate {
  key: string;
  label: string;
  build: () => DocDocument;
}

