  );
};

/** Mass-spec trace, ported from the point generator at TraceAnalysisViewer.tsx:18-27. */
const MassSpec = ({ seed }: { seed: number }) => {
  const peaks = (s: number) => {
    const points = ['0,100'];
    for (let i = 1; i <= 20; i += 1) {
      const x = i * 5;
      const major = (s * i) % 7 === 0;
      const y = major ? 10 + ((s * i) % 20) : 75 + ((s * i) % 20);
      points.push(`${x},${y}`);
    }
    points.push('100,100');
    return points.join(' ');
  };

  return (







  );
};

