export const TERMINAL_BLOCK_TYPES: readonly TerminalBlockType[] = [
  'prompt_line',
  'output_stream',
  'status_banner',
  'encryption_flow',
  'hash_matrix',
  'file_tree',
  'ascii_panel',
  'packet_trace',
  'spacer',
] as const;

export const TERMINAL_OVERLAY_BLOCK_TYPES: readonly TerminalBlockType[] = [] as const;

/* ------------------------------------------------------------------ *
 * The document envelope
 * ------------------------------------------------------------------ */

export interface TerminalDocument {
  v: 1;
  theme: TerminalTheme;
  blocks: TerminalBlock[];
}

/** Stored under `metadata.terminal`. */
export interface TerminalMetadata {
  terminal?: TerminalDocument;
}

export const DEFAULT_TERMINAL: TerminalDocument = {
  v: 1,
  theme: 'terminal',
  blocks: [],
};

/* ------------------------------------------------------------------ *
 * Helpers
 * ------------------------------------------------------------------ */

export const clampTerminalSpan = clampSpan;
export const nextTerminalBlockId = nextBlockId;

export const normalizeTerminal = (metadata: unknown): TerminalDocument => {
  const raw = (metadata as TerminalMetadata | null | undefined)?.terminal;
  if (!raw || typeof raw !== 'object') {
    return { ...DEFAULT_TERMINAL, blocks: [] };
  }

  const theme: TerminalTheme = TERMINAL_THEMES.includes(raw.theme) ? raw.theme : 'terminal';

  const blocks = Array.isArray(raw.blocks)
    ? raw.blocks
        .filter((b: unknown): b is TerminalBlock => {
          if (!b || typeof b !== 'object' || !('type' in b)) return false;
          const block = b as Record;
          if (!('props' in block) || block.props === null || typeof block.props !== 'object') return false;
          return TERMINAL_BLOCK_TYPES.includes(block.type as TerminalBlockType);
        })
    : [];

  return { v: 1, theme, blocks };
};

export const ensureTerminalBlockIds = (blocks: TerminalBlock[]): TerminalBlock[] =>
  blocks.map((b) => {
    const withId = b.id ? b : ({ ...b, id: nextBlockId() } as TerminalBlock);
    return withId;
  });

/* ------------------------------------------------------------------ *
 * Type guards for discriminated unions
 * ------------------------------------------------------------------ */

export const isTerminalBlock = (
  block: TerminalBlock,
  type: T
): block is Extract => block.type === type;

export const isTerminalBlockType = (block: TerminalBlock, type: TerminalBlockType): boolean =>
  block.type === type;

export function assertTerminalBlock(
  block: TerminalBlock,
  type: T
): asserts block is Extract {
  if (block.type !== type) {
    throw new Error(`Expected block type "${type}", got "${block.type}"`);
  }
}

export function getTerminalBlockProps(
  block: TerminalBlock,
  type: TerminalBlockType
): TerminalBlock['props'] | null {
  if (block.type !== type) return null;
  return block.props;
}

export type Result =
  | { isSuccess: true; value: T; errorMessage?: never }
  | { isSuccess: false; value?: never; errorMessage: E };

export const success = (value: T): Result => ({
  isSuccess: true,
  value,
});

export const failure = (errorMessage: E): Result => ({
  isSuccess: false,
  errorMessage,
});

/**
 * Resolves backend-served static asset paths to absolute URLs.
 *
 * Block images and procedural signature faces are served by the Laravel app out
 * of `public/assets/`, but the frontend runs on a different origin in dev
 * (Vite on :5173, API on :8000). A relative path like `/assets/x.png` inside
 * `metadata.doc` would therefore resolve against the Vite origin and 404, and
 * `Evidence::imgUrl()`'s `config('app.url')` prefixing does not apply to the doc
 * envelope -- that accessor is bound to the `img_url` column only.
 *
 * Absolute URLs and data URIs are passed through untouched, so a document may
 * legitimately point at a CDN.
 */

const API_URL = (import.meta.env.VITE_API_URL as string | undefined)?.replace(/\/+$/, '');

/** `http://localhost:8000/api` -> `http://localhost:8000`. */
const assetOrigin = (): string => (API_URL ?? '').replace(/\/api$/, '');

const FALLBACK_ORIGIN = 'http://localhost:8000';

export const assetUrl = (path: string): string => {
  const trimmed = (path ?? '').trim();
  if (!trimmed) return '';

  // Already absolute, protocol-relative, or inline data.
  if (/^([a-z][a-z0-9+.-]*:)?\/\//i.test(trimmed) || /^data:/i.test(trimmed)) return trimmed;

  return `${assetOrigin() || FALLBACK_ORIGIN}/${trimmed.replace(/^\/+/, '')}`;
};

/**
 * Small pure helpers for defensively reading values that cross the API boundary.
 *
 * The backend hands back error shapes that are inconsistent by design of
 * accident -- a bare string, a Laravel `ErrorBag` (`{ message: {...} }`),
 * an `Error` instance, or an already-extracted field. These helpers make the
 * consumers (`useGameMutation`, the realtime `channel.listen` handlers)
 * independent of that shape.
 */

/** Shape of the error envelopes the API layer rejects with. */
type MaybeStringable = { message?: unknown };

/** Reads a `message` off a value without trusting its type. */
const readMessage = (val: unknown): unknown => {
  if (val === null || typeof val !== 'object') return undefined;
  return (val as MaybeStringable).message;
};

/**
 * Coerces an unknown error/payload value into a renderable string.
 *
 * Guards against React's "Objects are not valid as a React child" crash by
 * guaranteeing a `string` return. Anything that is not a string (or a string
 * reachable one level down through `message`) yields the `fallback`.
 */
export const getSafeString = (val: unknown, fallback: string): string => {
  if (!val) return fallback;
  if (typeof val === 'string') return val;

  const message = readMessage(val);
  if (typeof message === 'string') return message;

  const nested = readMessage(message);
  if (typeof nested === 'string') return nested;

  return fallback;
};

/** Anything that can be merged by identity -- every room entity has a numeric `id`. */
export type Identifiable = { id: number | string };

/**
 * Merges a realtime patch payload into an existing collection.
 *
 * Used by the `channel.listen('ItemsUnlocked' | 'LevelTransitioned')`
 * handlers in `GameRoom`, which receive only the *changed* rows but must
 * return the whole array to the state updater -- a partial payload is not a
 * replacement for the collection.
 *
 * Semantics preserved from the original inline implementation:
 *   - existing entries keep their original position and take the new value,
 *   - unknown entries are appended in payload order,
 *   - duplicate ids within the payload collapse to the last one.
 *
 * Pure: no mutation of either argument.
 */
export const patchArray = (oldArr: T[] = [], newItems: T[] = []): T[] => {
  const map = new Map();
  oldArr.forEach((item) => map.set(item.id, item));
  newItems.forEach((item) => map.set(item.id, item));
  return Array.from(map.values());
};

import DOMPurify from 'dompurify';

const PURIFY_CONFIG = {
  ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a', 'p', 'span', 'br', 'ul', 'li', 'ol', 'div'],
  ALLOWED_ATTR: ['class', 'href', 'target'],
};

/**
 * Sanitizes dirty HTML strings to prevent XSS attacks.
 * Preserves specific safe tags and attributes required for immersive formatting.
 */
export const sanitizeHtml = (dirty: string): string => {
  return DOMPurify.sanitize(dirty, PURIFY_CONFIG);
};

/**
 * Centralised Web Storage access layer.
 *
 * Every consumer in the app previously hand-rolled its own
 * `storage.getItem` -> `JSON.parse` -> `try/catch` block, which meant:
 *   - corrupted values threw `SyntaxError` straight into React render,
 *   - some call sites silently swallowed the error and kept the bad value,
 *   - some call sites purged, others did not.
 *
 * These helpers make the failure mode uniform: a read never throws, and a
 * value that cannot be parsed is evicted so the next read starts clean.
 * Writes never throw either -- a full quota or a browser in strict/private
 * mode degrades to "state is not persisted", not to a crashed component.
 */

export type StorageType = 'local' | 'session';

const resolveStore = (type: StorageType): Storage | null => {
  try {
    return type === 'local' ? localStorage : sessionStorage;
  } catch (error) {
    // Touching the global throws a SecurityError in sandboxed frames and in
    // browsers configured to block third-party storage.
    console.warn(`Web ${type}Storage is unavailable in this context.`, error);
    return null;
  }
};

/**
 * Safely reads and parses a JSON value out of Web Storage.
 *
 * If the stored payload is unparseable, the corrupted key is removed and the
 * `fallback` is returned, so callers never have to guard the parse themselves.
 * An absent key returns the `fallback` without touching storage.
 *
 * NOTE: "unparseable" includes a bare, unquoted legacy string. That eviction is
 * intentional, but it means any value written before the JSON migration was
 * lost on its first read rather than migrated. See the accepted-data-loss note
 * in AgentNotepad.tsx for the one key where this was actually observed.
 *
 * Keys holding opaque scalars must use getSafeStringStorage below instead, which
 * has no purge path and therefore cannot lose data.
 */
export const getSafeStorage = (type: StorageType, key: string, fallback: T): T => {
  const store = resolveStore(type);
  if (!store) return fallback;

  let raw: string | null;
  try {
    raw = store.getItem(key);
  } catch (error) {
    console.warn(`Failed to read "${key}" from ${type}Storage.`, error);
    return fallback;
  }

  if (raw === null) return fallback;

  try {
    return JSON.parse(raw) as T;
  } catch (error) {
    // Self-healing: a single bad write must not brick the feature forever.
    console.warn(`Corrupted JSON at ${type}Storage key "${key}". Purging.`, error);
    try {
      store.removeItem(key);
    } catch (purgeError) {
      console.warn(`Failed to purge corrupted ${type}Storage key "${key}".`, purgeError);
    }
    return fallback;
  }
};

/**
 * Serialises and writes a value to Web Storage. Never throws.
 */
export const setSafeStorage = (type: StorageType, key: string, value: T): void => {
  const store = resolveStore(type);
  if (!store) return;

  try {
    store.setItem(key, JSON.stringify(value));
  } catch (error) {
    // Quota exceeded, private mode, or serialisation of a cyclic value.
    console.warn(`Failed to persist "${key}" to ${type}Storage.`, error);
  }
};

/**
 * Reads an OPAQUE string value out of Web Storage.
 *
 * This is deliberately NOT the JSON variant above. Some keys -- most
 * importantly `auth_token` -- are stored and read as bare strings, and their
 * value is interpolated into outbound headers (`Bearer ${token}`). Running
 * them through `setSafeStorage` would persist the value *with literal quote
 * characters*, and `getSafeStorage` would throw on a legacy bare value and
 * then purge it. Both failure modes are silent auth-breaking bugs.
 *
 * Therefore this pair preserves the on-disk format byte-for-byte: no
 * serialisation, no parsing, and consequently no corruption path and no
 * eviction. It exists purely so that a blocked or unavailable Web Storage
 * degrades to the fallback instead of throwing into a render or a request.
 */
export const getSafeStringStorage = (type: StorageType, key: string, fallback: string): string => {
  const store = resolveStore(type);
  if (!store) return fallback;

  try {
    return store.getItem(key) ?? fallback;
  } catch (error) {
    console.warn(`Failed to read "${key}" from ${type}Storage.`, error);
    return fallback;
  }
};

/**
 * Writes an opaque string to Web Storage verbatim. Never throws.
 */
export const setSafeStringStorage = (type: StorageType, key: string, value: string): void => {
  const store = resolveStore(type);
  if (!store) return;

  try {
    store.setItem(key, value);
  } catch (error) {
    // Quota exceeded or private/restricted mode.
    console.warn(`Failed to persist "${key}" to ${type}Storage.`, error);
  }
};

/**
 * Removes a single key from Web Storage. Never throws.
 */
export const removeSafeStorage = (type: StorageType, key: string): void => {
  const store = resolveStore(type);
  if (!store) return;

  try {
    store.removeItem(key);
  } catch (error) {
    console.warn(`Failed to remove "${key}" from ${type}Storage.`, error);
  }
};

/**
 * Purges every session key scoped to a room.
 *
 * Room-scoped keys are written under both the invite code and the numeric id
 * (`room__guilty_characters`, `room__viewed_evidence`, ...),
 * so both prefixes are swept. Used when leaving a room and when a verdict
 * finalises the case.
 */
export const clearRoomSessionData = (roomId: string | number, inviteCode?: string): void => {
  const store = resolveStore('session');
  if (!store) return;

  const prefixes = new Set();
  if (inviteCode !== undefined && inviteCode !== null && `${inviteCode}` !== '') {
    prefixes.add(`room_${inviteCode}`);
  }
  if (roomId !== undefined && roomId !== null && `${roomId}` !== '') {
    prefixes.add(`room_${roomId}`);
  }
  if (prefixes.size === 0) return;

  try {
    Object.keys(store).forEach((key) => {
      for (const prefix of prefixes) {
        if (key.includes(prefix)) {
          store.removeItem(key);
          return;
        }
      }
    });
  } catch (error) {
    console.warn('Failed to purge room session data.', error);
  }
};

import type { User } from '@/types';
import { getSafeStorage } from './storage';

/**
 * Key under which the authenticated user is mirrored into `localStorage` by
 * the login flow in `MainMenu`.
 */
export const AUTH_USER_KEY = 'auth_user';

/**
 * Reads the currently authenticated user out of `localStorage`.
 *
 * Replaces the `JSON.parse(localStorage.getItem('auth_user'))` pattern that
 * was duplicated in `useInvestigationPhase`, `AgentNotepad`, `CampaignTab`,
 * `LocationPhase` and `MainMenu` -- each of which had its own, differently
 * broken, parse guard.
 *
 * Returns `null` when nobody is signed in, when the payload is corrupt
 * (the corrupt key is purged by `getSafeStorage`), or when storage is
 * unavailable.
 */
export const getLocalUser = (): User | null => {
  return getSafeStorage('local', AUTH_USER_KEY, null);
};
